import {ACTIVE_GEMS,SUPPORT_GEMS,compileSkill} from './gems.js';
import {bossName} from './monsters.js';
import {buildPanel} from './build-ui.js';
import {Game} from './engine.js';
import {Renderer} from './renderer.js';
import {Input} from './input.js';
import {AudioSystem} from './audio.js';
import {RARITIES} from './data.js';
const $=id=>document.getElementById(id),overlay=$('overlay'),audio=new AudioSystem();
let best=0;try{best=Number(localStorage.getItem('emberfall-best'))||0}catch{}
let game,input,announceTimeout,buildReturn=null;const format=t=>`${String(Math.floor(t/60)).padStart(2,'0')}:${String(Math.floor(t%60)).padStart(2,'0')}`;
function modal(html){overlay.innerHTML=html;const button=overlay.querySelector('button');if(button)button.focus({preventScroll:true});if(input)input.reset()}
function announce(text){$('announcement').textContent=text;$('announcement').style.opacity=1;clearTimeout(announceTimeout);announceTimeout=setTimeout(()=>$('announcement').style.opacity=0,3500)}
function onEvent(type,data){if(type==='sound'){audio.play(data);return}if(type==='reset')return;if(type==='loadout')updateSkills();if(type==='levelup')showChoices(data);if(type==='upgrade'){if(game.state==='playing')overlay.innerHTML='';updateSkills()}if(type==='pause')showPause();if(type==='resume')overlay.innerHTML='';if(type==='boss'){announce(`${data}，已經甦醒`);$('bossName').textContent=`♜ ${data}`;$('obj1').className='done';$('obj2').className='active';$('bossHud').classList.remove('hidden')}if(type==='end')showEnd(data)}
game=new Game({onEvent});const renderer=new Renderer($('game'));input=new Input(()=>{if(game.state==='build')closeBuild();else game.pause()},()=>{audio.unlock();game.dash()});
function openBuild(){if(!['playing','paused','menu','levelup'].includes(game.state))return;buildReturn=game.state;game.state='build';input.reset();buildPanel(game,modal,closeBuild)}
function closeBuild(){const previous=buildReturn||'paused';buildReturn=null;game.state=previous;input.reset();updateSkills();if(previous==='menu')showStart();else if(previous==='levelup')showChoices(game.choices);else if(previous==='paused')showPause();else overlay.innerHTML=''}
function start(){audio.unlock();input.reset();clearTimeout(announceTimeout);$('announcement').style.opacity=0;game.reset();renderer.camera={x:1200,y:1200};overlay.innerHTML='';$('obj1').className='active';$('obj2').className='';$('obj3').className='';$('bossHud').classList.add('hidden');$('seedText').textContent=`世界種子 ${game.seed.toString(16).toUpperCase()}`;updateSkills();announce('按 B 或 ◈ 開啟技能工坊，自由搭配寶石')}
function showStart(){modal(`<div class="start-screen"><div class="sigil">✧</div><span class="eyebrow">THE FIRE STILL REMAINS</span><h1>EMBERFALL</h1><h2>燼 境</h2><p>踏入不斷變化的荒野，以餘燼化為法術。<br>連接技能寶石，挑戰三位遠古首領之一。</p><div class="start-actions"><button class="primary" id="start">開始遠征 <span aria-hidden="true">↗</span></button><button class="secondary" id="startBuild">◈ 配置技能組</button></div><div class="start-meta"><span>◈ 6 種技能 × 10 顆輔助</span><span>◷ 約 4–6 分鐘一局</span></div>${best?`<p style="font-size:11px;margin-top:18px">最長存活 ${format(best)}</p>`:''}</div>`);$('start').onclick=start;$('startBuild').onclick=openBuild}
function showChoices(choices){modal(`<div class="modal"><span class="eyebrow">LEVEL ${game.player.level} / 選擇你的道路</span><h2>讓餘燼，化為力量。</h2><p>選擇一項強化 · 本次升級已回復 10 點生命<br>技能寶石可在 ◈ 工坊自由裝配</p><div class="choices">${choices.map(({skill,rarity},i)=>`<button class="choice ${rarity}" data-choice="${i}"><span class="rarity">${RARITIES[rarity].name} / ${rarity.toUpperCase()}</span><span class="glyph">${skill.icon}</span><strong>${skill.name}</strong><p>${skill.desc(RARITIES[rarity].mult)}</p><span class="select">選擇 ${i+1} ↗</span></button>`).join('')}</div></div>`);overlay.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>game.choose(Number(b.dataset.choice)))}
function showPause(){modal(`<div class="modal"><span class="eyebrow">TAKE A BREATH</span><h2>火焰，為你停留。</h2><p>遠征已暫停。<br>移動：WASD / 方向鍵 / 觸控搖桿<br>衝刺：空白鍵 / 右下按鈕，冷卻 3 秒。</p><div class="modal-actions"><button id="resume" class="primary">繼續遠征</button><button id="pauseBuild" class="secondary">◈ 技能工坊</button><button id="restart" class="secondary">重新開始</button></div></div>`);$('resume').onclick=()=>game.pause();$('restart').onclick=start;$('pauseBuild').onclick=openBuild}
function showEnd(won){best=Math.max(best,game.time);try{localStorage.setItem('emberfall-best',best)}catch{}if(won){$('obj1').className='done';$('obj2').className='done';$('obj3').className='done';$('bossHud').classList.add('hidden')}modal(`<div class="modal"><div class="sigil">${won?'✺':'✧'}</div><span class="eyebrow">${won?'EXPEDITION COMPLETE':'THE EMBERS REMAIN'}</span><h2>${won?'火光，再度重燃。':'旅途尚未結束。'}</h2><p>${won?`${bossName(game.boss)}已倒下。這片荒野記住了你的名字。`:'你的餘燼將化為下一次旅途的火種。'}</p><div class="results"><div><strong>${format(game.time)}</strong><span>存活時間</span></div><div><strong>${game.kills}</strong><span>擊敗敵人</span></div><div><strong>${game.player.level}</strong><span>最終等級</span></div></div><div class="modal-actions"><button id="again" class="primary">再次遠征 ↗</button></div></div>`);$('again').onclick=start}
function updateSkills(){const items=Object.values(game.owned);$('skillCount').textContent='3 組';$('skillList').innerHTML=game.links.map((row,i)=>{const a=ACTIVE_GEMS[row.active],stats=compileSkill(row,game.player,game.gemLevels);return `<div class="loadout-link"><div class="skill-row"><span class="skill-icon" style="color:${a.color};border-color:${a.color}">${a.icon}</span><div><strong>${a.name}</strong><small>${Math.round(stats.damage)} 傷害 · ${stats.rate.toFixed(2)} 次/秒</small></div><span>${row.supports.filter(Boolean).length+1}L</span></div><p>${row.supports.filter(Boolean).map(id=>SUPPORT_GEMS[id].name).join(' ⟡ ')||'尚未連接輔助寶石'}</p></div>`}).join('')+items.map(({skill,rarity,count})=>`<div class="skill-row"><span class="skill-icon" style="color:${RARITIES[rarity].color}">${skill.icon}</span><div><strong>${skill.name}</strong><small>角色被動 · ${RARITIES[rarity].name}</small></div><span>×${count}</span></div>`).join('')}
function hud(){const p=game.player;$('hpText').textContent=`${Math.ceil(p.hp)} / ${Math.round(p.maxHp)}`;$('hpFill').style.width=`${p.hp/p.maxHp*100}%`;$('levelText').textContent=`LV. ${String(p.level).padStart(2,'0')}`;$('xpFill').style.width=`${Math.min(100,p.xp/p.nextXp*100)}%`;$('xpText').textContent=`${p.xp} / ${p.nextXp}`;$('timer').textContent=format(game.time);$('killText').textContent=`擊敗 ${game.kills}`;$('phaseText').textContent=game.bossSpawned?`終章 · ${bossName(game.boss)}`:game.time>90?'第二章 · 暗潮湧動':'第一章 · 甦醒之森';$('dashState').textContent=p.dashCooldown>0?`衝刺 · ${p.dashCooldown.toFixed(1)}s`:'SPACE · 衝刺就緒';$('dashTouch').style.opacity=p.dashCooldown>0?'.4':'1';if(game.boss){$('bossHp').textContent=`${Math.max(0,Math.ceil(game.boss.hp))} / ${Math.round(game.boss.maxHp)}`;$('bossFill').style.width=`${Math.max(0,game.boss.hp/game.boss.maxHp*100)}%`}}
$('build').onclick=()=>game.state==='build'?closeBuild():openBuild();$('buildSide').onclick=openBuild;$('pause').onclick=()=>{if(game.state==='build')closeBuild();else game.pause()};$('sound').onclick=()=>{$('sound').textContent=audio.toggle()?'♫':'♪̸';$('sound').setAttribute('aria-label',audio.enabled?'關閉音效':'開啟音效')};
document.addEventListener('visibilitychange',()=>{if(document.hidden&&game.state==='playing')game.pause();input.reset()});window.addEventListener('blur',()=>{if(game.state==='playing')game.pause()});window.addEventListener('keydown',e=>{if(e.key.toLowerCase()==='b'&&!e.repeat){e.preventDefault();game.state==='build'?closeBuild():openBuild()}if(game.state==='levelup'&&['1','2','3'].includes(e.key))game.choose(Number(e.key)-1)});
// Fixed simulation steps prevent frame-rate-dependent movement and tunnelling.
let previous=performance.now(),accumulator=0,uiClock=0;function frame(now){const dt=Math.min((now-previous)/1000,.1);previous=now;if(game.state==='playing'){accumulator+=dt;let steps=0;while(accumulator>=1/60&&steps<6){game.step(1/60,input.direction());accumulator-=1/60;steps++}}else accumulator=0;renderer.draw(game,now/1000);uiClock+=dt;if(uiClock>.1){hud();uiClock=0}requestAnimationFrame(frame)}
showStart();updateSkills();hud();requestAnimationFrame(frame);
